  const rows = this.db
    .query(`SELECT * FROM ${this.evidenceTable} WHERE canonical_id = ? ORDER BY id`)
    .all(canonicalId) as Array<Record<string, unknown>>;
  let confirmed = 0, refuted = 0, unresolved = 0;
  let prevHash = "GENESIS";
  for (const raw of rows) {
    const outcome = String(raw["outcome"] ?? "");
    const firedAt = String(raw["fired_at"] ?? "");
    const sig = String(raw["sig"] ?? "");
    // Verify the chain-of-signature on the evidence row
    const expectedSig = crypto
      .createHmac("sha256", this.key)
      .update(`${prevHash}|${JSON.stringify({ c: canonicalId, at: firedAt, o: outcome })}`)
      .digest("hex");
    const a = Buffer.from(expectedSig, "hex");
    const b = Buffer.from(sig, "hex");
    if (a.length !== b.length || a.length === 0 || !crypto.timingSafeEqual(a, b)) {
      break; // forged or tampered evidence — stop counting here
    }
    if (outcome === "confirmed") confirmed++;
    else if (outcome === "refuted") refuted++;
    else unresolved++;
    prevHash = sig;
  }
  return { confirmed, refuted, unresolved };
}

